let literal_hash = "ab205445a67561a6baa67431f82f89bdfccbea46021ca593fa762d831b57dd99"
let cases = Json.array literals
let case name = List.find(fun raw -> Json.string(get "name" raw)=name) cases
let request raw = V.Request.of_json(get "request" raw)
let check raw record =
  require (V.Record.fingerprint record=Json.string(get "fingerprint" raw)) "Complete workflow identity changed";
  require (same (V.Record.to_json record) (get "expected" raw)) "Complete workflow report changed"
let error code action =
  try ignore(action()); failwith ("Expected "^code) with Diagnostic.Error value -> require(value.code=code) value.code
let semantic message action =
  try ignore(action()); failwith "Expected workflow rejection" with Diagnostic.Error value -> require(value.message=message) value.message
let replace key value raw = Json.Object((key,value)::List.remove_assoc key(Json.object_fields raw))
let () =
  require(Canonical.fingerprint literals=literal_hash && List.length cases=12) "Original workflow literal census changed";
  List.iter(fun raw ->
    let authority=request raw in
    let result=K.run authority in check raw result;
    let historical=V.Record.of_json(get "expected" raw) in
    check raw (K.replay ~expected_request:authority historical)) cases;
  let raw=case "candidate_pass" in
  let authority=request raw in
  let record,usage=K.run_with_usage authority in
  require(usage.evaluations=1 && usage.work_charged>0) "Workflow evaluator accounting missing";
  check raw(K.run ~limits:(K.make_limits ~max_work:usage.work_charged ()) authority);
  error "workflow_work_limit" (fun()->K.run ~limits:(K.make_limits ~max_work:(usage.work_charged-1) ()) authority);
  let parent=W.create ~profile:"workflow-test" ~error_code:"parent_workflow_limit" ~maximum:usage.work_charged () in
  check raw(K.run ~parent authority);require(W.remaining parent=0) "Work escaped shared parent";
  let parent=W.create ~profile:"workflow-test" ~error_code:"parent_workflow_limit" ~maximum:(usage.work_charged-1) () in
  error "parent_workflow_limit" (fun()->K.run ~parent authority);
  let budget=B.create () in
  B.reserve_request budget (get "request" raw);
  let decoded=K.decode_request_in ~budget (get "request" raw) in
  check raw(K.run_in ~budget decoded);
  let budget=B.create () in
  B.reserve_request budget (get "expected" raw);
  let historical=K.decode_record_in ~budget (get "expected" raw) in
  check raw(K.replay_in ~budget ~raw_record:(get "expected" raw) ~expected_request:authority historical);
  let changed=V.Request.of_json(replace "until" (Json.Float 9.) (get "request" raw)) in
  semantic "Verification operation differs from independent authority." (fun()->K.replay ~expected_request:changed record);
  let report=get "result" (get "expected" raw) in
  let dependencies=get "dependencies" report in
  let settings=replace "verification_workflow" (Json.String "forged") (get "settings" dependencies) in
  let report=replace "dependencies" (replace "settings" settings dependencies) report in
  let forged=V.Record.of_json(replace "result" report (get "expected" raw)) in
  semantic "Verification evidence is stale, altered or unsupported by current tools." (fun()->K.replay ~expected_request:authority forged);
  let budget=B.create () in
  semantic "Verification evidence is stale, altered or unsupported by current tools." (fun()->
    K.replay_in ~budget ~raw_record:(replace "extra" Json.Null (get "expected" raw)) ~expected_request:authority record);
  let _,replay_usage=K.replay_with_usage ~expected_request:authority record in
  require(replay_usage.evaluations=1 && replay_usage.request_bytes>usage.request_bytes) "Replay failed to account historical and independent inputs";
  check raw(K.run authority);
  Printf.printf "Native synthetic workflow: 12 complete original records, both modes/all operations/all outcomes, fresh replay and shared budget controls passed\n"
